function parse(v) {
  const [core, prerelease] = v.split('-');
  const [major, minor, patch] = core.split('.').map(Number);
  return { major, minor, patch, prerelease };
}

export function satisfies(version, range) {
  const v = parse(version);
  const lower = parse(range.replace('^', ''));
  // A prerelease never satisfies a range whose lower bound carries no prerelease tag.
  if (v.prerelease && !lower.prerelease) return false;
  if (v.major !== lower.major) return false;
  if (v.minor !== lower.minor) return v.minor > lower.minor;
  return v.patch >= lower.patch;
}

